import React, { useState } from 'react';
import './AdminPanel.css'; // Asegúrate de tener el archivo de estilos

function AdminPanel() {
  const [users, setUsers] = useState([
    { id: 1, name: 'Juan Pérez', email: 'juan@example.com', role: 'usuario' },
    { id: 2, name: 'Ana Gómez', email: 'ana@example.com', role: 'administrador' },
    { id: 3, name: 'Luis Martínez', email: 'luis@example.com', role: 'usuario' },
  ]);

  // Función para manejar el cambio de rol de un usuario
  const handleChangeRole = (id, newRole) => {
    setUsers(users.map(user => 
      user.id === id ? { ...user, role: newRole } : user
    ));
  };

  // Función para manejar la baja de un usuario
  const handleDeleteUser = (id) => {
    setUsers(users.filter(user => user.id !== id));
  };

  // Función para mostrar más información
  const handleViewMore = (id) => {
    const user = users.find(u => u.id === id);
    alert(`Información de ${user.name}: ${user.email}, Rol: ${user.role}`);
  };

  return (
    <div className="admin-panel">
      <h1>Panel de Administrador</h1>
      <div className="user-list">
        {users.map(user => (
          <div key={user.id} className="user-card">
            <div className="user-info">
              <span><strong>{user.name}</strong></span>
              <span>{user.email}</span>
              <span>Rol: {user.role}</span>
            </div>
            <div className="user-actions">
              <button onClick={() => handleViewMore(user.id)}>Ver Más</button>
              <button onClick={() => handleChangeRole(user.id, user.role === 'usuario' ? 'administrador' : 'usuario')}>
                Cambiar Rol
              </button>
              <button onClick={() => handleDeleteUser(user.id)}>Dar de Baja</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default AdminPanel;
